import {instrumentLessons,stepMatches} from './instrument-content.mjs';
export function mountInstrumentTutor(api){const $=id=>document.getElementById(id);let lesson=null,index=0,wasHidden=true,lastFocus=null;let completed=[];try{completed=JSON.parse(api.storage.getItem('circuitlab-instruments-v8')||'[]');}catch{}
const rail=document.createElement('div');rail.className='instrumentRail';rail.innerHTML='<span>INSTRUMENTOS</span><button data-instrument="meter">Multímetro</button><button data-instrument="scope">Osciloscopio</button><button data-instrument="generator">Generador</button>';document.querySelector('header').after(rail);
const bar=document.createElement('div');bar.className='instrumentDockBar';bar.innerHTML='<b>Laboratorio de señales</b><button id="expandInstrument">⛶ Ampliar</button><button id="closeInstrument">Volver a la placa / curso ×</button>';$('scopePage').prepend(bar);
const contextual=document.createElement('div');contextual.className='contextInstruments';contextual.innerHTML='<h3>Medir en el tiempo</h3><p>Compara entrada y salida con el osciloscopio y una excitación conocida.</p><button data-instrument="scope">Abrir osciloscopio</button><button data-instrument="generator">Configurar generador</button><p id="signalModelNotice"></p>';document.querySelector('.instruments').prepend(contextual);
function close(){const el=$('scopePage');if(!el.classList.contains('instrumentOverlay'))return;el.classList.remove('instrumentOverlay','instrumentWide');el.hidden=wasHidden;document.querySelectorAll('.tutorTarget').forEach(e=>e.classList.remove('tutorTarget'));lastFocus?.focus?.();}
function open(which='scope',id){lastFocus=document.activeElement;const el=$('scopePage');if(!el.classList.contains('instrumentOverlay'))wasHidden=el.hidden;el.hidden=false;el.classList.add('instrumentOverlay');const board=api.board();$('signalModelNotice').textContent=board==='rc'?'RC disponible como experimento equivalente. Las sondas de señales se conectan en el panel del osciloscopio.':'Esta placa no tiene simulación temporal completa. El laboratorio usa un experimento RC o directo separado y claramente identificado.';
if(id)start(id);else if(!lesson)start(which==='generator'?'generador':'sondas');else render();$('scopePage').scrollTop=0;}
$('closeInstrument').onclick=close;$('expandInstrument').onclick=()=>$('scopePage').classList.toggle('instrumentWide');document.addEventListener('keydown',e=>{if(e.key==='Escape')close();});document.addEventListener('click',e=>{const b=e.target.closest('[data-instrument]');if(b){if(b.dataset.instrument==='meter'){close();api.openLab();document.querySelector('.meter').scrollIntoView({behavior:'smooth',block:'start'});}else open(b.dataset.instrument,b.dataset.lesson);}});
for(const id of ['navcourse','navlibrary','navlab','navscope'])$(id).addEventListener('click',close,{capture:true});
const mapping=['sondas','sondas','sondas','generador','amplitud','carga','generador','disparo','metodo','offset','sondas','metodo'];document.addEventListener('circuitlab:instruments',e=>open(e.detail?.kind||'scope',e.detail?.lesson||mapping[e.detail?.unit]||'generador'));
function start(id){lesson=instrumentLessons.find(x=>x.id===id)||instrumentLessons[0];index=0;render();}
function render(){const step=lesson.steps[index];$('signalTutor').innerHTML=`<section class="signalTutor"><div class="signalTutorHead"><div><span class="eyebrow">APRENDE EL INSTRUMENTO · ${completed.length}/9 GUÍAS</span><h2>${lesson.title}</h2></div><select id="instrumentLesson" aria-label="Guía de instrumentos">${instrumentLessons.map(l=>`<option value="${l.id}" ${l.id===lesson.id?'selected':''}>${completed.includes(l.id)?'✓ ':''}${l.title}</option>`).join('')}</select></div><div class="signalProgress">${lesson.steps.map((s,i)=>`<i class="${i<=index?'on':''}"></i>`).join('')}</div><p><b>Paso ${index+1}/${lesson.steps.length} · ${step[0]}</b></p><p>${step[1]}</p><div class="signalTutorActions"><button id="instrumentBack" ${index===0?'disabled':''}>← Anterior</button><button id="findControl">Ver el control</button><button id="instrumentCheck" class="academyPrimary">Comprobar paso →</button></div><p id="instrumentFeedback" role="status"></p><small>Las comprobaciones leen los controles reales. Las guías no rellenan tu respuesta.</small></section>`;$('instrumentLesson').onchange=e=>start(e.target.value);$('instrumentBack').onclick=()=>{index--;render();};$('findControl').onclick=()=>{const target=$(step[2]);target?.scrollIntoView({behavior:'smooth',block:'center'});target?.focus();};document.querySelectorAll('.tutorTarget').forEach(e=>e.classList.remove('tutorTarget'));$(step[2])?.classList.add('tutorTarget');$('instrumentCheck').onclick=()=>{const values=Object.fromEntries(lesson.steps.map(s=>[s[2],$(s[2])?.value]));if(!api.scope.isRunning()){$('instrumentFeedback').textContent='Reanuda la adquisición antes de comprobar la señal.';return;}if(!stepMatches(step,values)){$('instrumentFeedback').textContent='Revisa '+step[0].toLowerCase()+'. El control resaltado todavía no tiene el ajuste indicado.';return;}if(index<lesson.steps.length-1){index++;render();}else{completed=[...new Set([...completed,lesson.id])];try{api.storage.setItem('circuitlab-instruments-v8',JSON.stringify(completed));}catch{}document.dispatchEvent(new CustomEvent('circuitlab:progress'));$('instrumentFeedback').textContent='✓ Guía completada. Compara las formas de onda y explica el resultado antes de pasar a otra guía.';$('instrumentCheck').textContent='Siguiente guía →';$('instrumentCheck').onclick=()=>start(instrumentLessons[(instrumentLessons.indexOf(lesson)+1)%instrumentLessons.length].id);}};}
start('generador');return {open,close};}
